/******************CREATE UNINSTALLATION PROCEDURE********************/ CREATE PROCEDURE "DA_CA_UNINSTALL" (IN SchemaName VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_DATA_TBL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_DATA_TBL_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_MODEL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_MODEL_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_TRAIN_DATA_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_TRAIN_DATA_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_PREDICT_DATA_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_PREDICT_DATA_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_TRAIN_RESULT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_TRAIN_RESULT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_TRAIN_RESULT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_TRAIN_RESULT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_PREDICT_RESULT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_NN_PREDICT_RESULT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_TRAIN_PDATA_TBL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TABLE DA_CA_PAL_NN_TRAIN_PDATA_TBL';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_NN_PREDICT_PDATA_TBL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TABLE DA_CA_PAL_NN_PREDICT_PDATA_TBL';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_TRAIN' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_NN_TRAIN');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_PREDICT' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_NN_PREDICT');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_CREATE_WRAPPER' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_NN_CREATE_WRAPPER"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_NN_PREDICTION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_NN_PREDICTION"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_INSTALL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_INSTALL"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LT_DATA_TBL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LT_DATA_TBL_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LT_PMMLMODEL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LT_PMMLMODEL_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_CONTROL_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_CONTROL_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_DATA_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_DATA_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_PREDICT_DATA_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_PREDICT_DATA_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_RESULT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_RESULT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_FITTED_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_FITTED_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_COEFFICIENT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_COEFFICIENT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_PREDICT_RESULT_T' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE DA_CA_PAL_LOGISTICR_PREDICT_RESULT_T';      END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_PDATA_TBL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TABLE DA_CA_PAL_LOGISTICR_PDATA_TBL';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM M_TABLES WHERE TABLE_NAME='DA_CA_PAL_LOGISTICR_PREDICT_PDATA_TBL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN     EXECUTE IMMEDIATE 'DROP TABLE DA_CA_PAL_LOGISTICR_PREDICT_PDATA_TBL';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LOGISTICR_REGRESSION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_LOGISTICR_REGRESSION');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LOGISTICR_FORECAST' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(:SchemaName, 'DA_CA_PAL_LOGISTICR_FORECAST');     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LT_CREATE_WRAPPER' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_LT_CREATE_WRAPPER"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LT_PREDICTION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_LT_PREDICTION"';     END IF; END
